CPC_QUESTIONS.push({"id":"fcc-cpc-254784","sourceQuestionId":"254784","t":"cpc-m16","moduleId":"cpc-m16","q":"Antônio afiançou Sérgio em contrato de mútuo celebrado com Thiago. Por meio de referido contrato, subscrito por duas testemunhas, Thiago emprestou R$ 10.000,00 (dez mil reais) a Sérgio e este se obrigou a devolver o dinheiro seis meses depois. Não adimplida a obrigação, no termo, Thiago propôs ação de execução contra Antônio, que, de acordo com o Código de Processo Civil,","o":["poderá nomear à penhora bens livres e desembargados de propriedade de Sérgio. Porém, seus bens ficarão sujeitos à execução se os de Sérgio não forem suficientes para satisfazer o crédito. Paga a dívida por Antônio, poderá executar Sérgio nos autos do mesmo processo.","deverá suportar sozinho a execução proposta por Thiago. Paga a dívida por Antônio, poderá executar Sérgio no âmbito de ação autônoma.","poderá nomear à penhora bens livres e desembargados de propriedade de Sérgio, sem que venham a ser atingidos bens de Antônio, mesmo que os de Sérgio sejam insuficientes para satisfação do crédito.","deverá suportar sozinho a execução proposta por Thiago. Paga a dívida por Antônio, poderá executar Sérgio nos autos do mesmo processo.","poderá nomear à penhora bens livres e desembargados de propriedade de Sérgio. Porém, seus bens ficarão sujeitos à execução se os de Sérgio não forem suficientes para satisfazer o crédito. Paga a dívida por Antônio, este não poderá executar Sérgio, por se tratar a fiança de contrato benéfico."],"a":0,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT1/TRT 1/2014 • TEC 254784","source":"FCC - JT TRT1/TRT 1/2014","subject":"Direito Processual Civil - Da Execução em Geral (arts. 771 a 796)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/254784","year":2014,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3670686","sourceQuestionId":"3670686","t":"cpc-m16","moduleId":"cpc-m16","q":"Sobre o processo de execução,","o":["quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo a ele mais proveitoso.","é nulo se o título executivo extrajudicial não corresponder a obrigação certa, líquida e exigível.","ao despachar a inicial, o juiz fixará honorários advocatícios de dez por cento, a serem pagos pelo executado, valor este que será reduzido pela metade se houver pagamento integral do débito no prazo de 15 (quinze) dias.","recaindo a penhora sobre bem imóvel, será intimado também o cônjuge do executado, salvo se forem casados em regime de comunhão parcial de bens.","a avaliação será feita pelo oficial de justiça, mesmo que uma das partes aceite a estimativa feita pela outra."],"a":1,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670686","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Disposições Gerais (arts. 797 a 805)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670686","year":2025,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2296264","sourceQuestionId":"2296264","t":"cpc-m16","moduleId":"cpc-m16","q":"De acordo com o que estabelece o Código de Processo Civil sobre o processo de execução,","o":["verificando que a petição inicial da execução está incompleta ou que não está acompanhada dos documentos indispensáveis à propositura da execução, o juiz determinará que o exequente a corrija, no prazo de 5 dias, sob pena de indeferimento.","a nulidade da execução somente será pronunciada pelo juiz, a requerimento da parte, mediante a apresentação de embargos à execução.","quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo mais gravoso para o executado.","ao propor a execução, incumbe ao exequente indicar a espécie de execução de sua preferência, quando por mais de um modo puder ser realizada.","nas obrigações alternativas, quando a escolha couber ao credor, esse será citado para exercer a opção e realizar a prestação dentro de 10 dias, se outro prazo não lhe foi determinado em lei ou em contrato."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT5/TRT 5/Judiciária/\"Sem Especialidade\"/2022 • TEC 2296264","source":"FCC - AJ TRT5/TRT 5/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Disposições Gerais (arts. 797 a 805)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2296264","year":2022,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-348443","sourceQuestionId":"348443","t":"cpc-m16","moduleId":"cpc-m16","q":"Manoel e Matias firmaram um contrato de compra e venda evolvendo obrigação alternativa, cuja escolha para realização da prestação caberá ao devedor Matias. Inadimplido o contrato, Manoel ajuíza ação de execução de título extrajudicial contra Matias. Matias será, então, citado para, em regra, exercer a opção e realizar a prestação dentro de","o":["10 dias.","15 dias.","30 dias.","20 dias.","5 dias."],"a":0,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT14/TRT 14/Administrativa/2016 • TEC 348443","source":"FCC - TJ TRT14/TRT 14/Administrativa/2016","subject":"Direito Processual Civil - Disposições Gerais (arts. 797 a 805)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/348443","year":2016,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126685","sourceQuestionId":"3126685","t":"cpc-m16","moduleId":"cpc-m16","q":"De acordo com o Código de Processo Civil, na execução para entrega de coisa certa,","o":["pode o executado, em embargos à execução, alegar retenção apenas por benfeitorias necessárias.","constada a perda ou deterioração da coisa, os prejuízos deverão ser apurados em ação autônoma, pelo procedimento comum.","alienada a coisa quando já litigiosa, o juiz ouvirá o terceiro adquirente e depois decidirá sobre sua entrega.","pode o executado, em embargos à execução, alegar retenção por benfeitorias necessárias ou úteis.","o devedor será citado para satisfazer a obrigação ou depositar o equivalente em dinheiro, sob pena de multa de 10% sobre o valor estimado da obrigação."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126685","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Execução Para a Entrega de Coisa (arts. 806 a 813)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126685","year":2024,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3570055","sourceQuestionId":"3570055","t":"cpc-m16","moduleId":"cpc-m16","q":"De acordo com o Código de Processo Civil, na execução da obrigação de fazer,","o":["o executado será citado para satisfazê-la no prazo de 5 dias, ainda que outro conste do título executivo.","é incabível a fixação de astreintes se estas não tiverem sido previstas no título executivo.","o juiz, ao despachar a inicial, fixará multa por atraso no cumprimento, a qual não poderá ser reduzida se tiver constado do título executivo.","o executado será citado para satisfazê-la no prazo de 15 dias, ainda que outro conste do título executivo.","se o executado não satisfizer a obrigação, pode o exequente, nos próprios autos do processo, requerer a satisfação da obrigação à custa do executado ou pedir perdas e danos."],"a":4,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3570055","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Execução das Obrigações de Fazer ou de Não Fazer (arts. 814 a 823)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3570055","year":2025,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3956211","sourceQuestionId":"3956211","t":"cpc-m17","moduleId":"cpc-m17","q":"Em uma ação de cobrança, Joana, fictamente citada, remanesceu revel, sendo-lhe nomeado defensor público para exercer as funções de curador especial. Na fase de cumprimento de sentença, foi realizada a penhora de bem imóvel de sua propriedade. À luz do Código de Processo Civil e da jurisprudência do STJ, a intimação da penhora","o":["é dispensada nos casos em que o executado tenha sido fictamente citado na fase de conhecimento, eis que se trata de ato processual de que não se exige ciência do executado citado fictamente que tenha restado revel.","deve ser realizada exclusivamente na pessoa do curador especial, uma vez que a intimação pessoal é prerrogativa institucional da Defensoria Pública, sendo inválida eventual intimação direta do executado citado por edital, em razão da inexistência de vínculo direto com o processo.","deve ser realizada pessoalmente ao executado, ainda que citado por edital na fase de conhecimento, não sendo suprida pela intimação pessoal do curador especial, que não se equipara a advogado constituído.","deve ser realizada exclusivamente na pessoa do curador especial, cabendo como matéria de defesa ao executado a alegação de inexigibilidade da obrigação ou eventual excesso de execução, a ser formulada por meio de exceção de pré-executividade.","na pessoa do curador especial é considerada válida, desde que feita pessoalmente ao Defensor Público e que não seja demonstrado prejuízo ao executado, aplicando-se o consagrado princípio da instrumentalidade das formas."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956211","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956211","year":2026,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3380062","sourceQuestionId":"3380062","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, a execução por quantia certa realiza-se pela expropriação de bens do executado, consistente em:","o":["alienação em leilão, somente.","adjudicação, alienação e apropriação de frutos e rendimentos de empresa ou de estabelecimentos e de outros bens.","adjudicação, comissão, leilão e praceamento.","praceamento e comissão, somente.","leilão, venda direta e desapropriação, somente."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025 • TEC 3380062","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3380062","year":2025,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3451258","sourceQuestionId":"3451258","t":"cpc-m17","moduleId":"cpc-m17","q":"Considere o Código de Processo Civil brasileiro para responder à questão. Quando realizada a penhora de um bem imóvel em processo de execução, sua avaliação, quando não forem necessários conhecimentos especializados, será realizada, em regra,","o":["pelo Oficial de Justiça.","por avaliador nomeado pelo Juiz.","pela parte exequente.","pela parte executada.","por perito nomeado pelo Juiz."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3451258","source":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3451258","year":2025,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3079821","sourceQuestionId":"3079821","t":"cpc-m17","moduleId":"cpc-m17","q":"Em relação à fase expropriatória do processo de execução,","o":["o exequente, que tem legitimidade para adjudicar o bem penhorado, não pode oferecer lance em leilão judicial, salvo se igual ou superior ao valor da avaliação.","a ampliação da penhora só é cabível após a tentativa de alienação judicial do bem penhorado.","sendo devedor partido político, são penhoráveis os recursos recebidos do fundo partidário.","o seguro de garantia judicial não equivale a dinheiro para fins de substituição da penhora, salvo se contratado em valor não inferior ao do débito exequendo, acrescido de 30%.","a impenhorabilidade dos valores depositados em caderneta de poupança não é oponível em ação de execução de obrigação alimentar, desde que esta seja decorrente de parentesco."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3079821","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3079821","year":2024,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3678193","sourceQuestionId":"3678193","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, em se tratando de divida não alimentar, é(são) penhorável(eis)","o":["os frutos e os rendimentos dos bens inalienáveis, à falta de outros bens penhoráveis do executado.","os honorários de profissional liberal.","os bens móveis úteis ao exercício da profissão do executado.","o seguro de vida do executado.","a quantia inferior a 40 salários-mínimos depositada em caderneta de poupança."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT7/TRT 7/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3678193","source":"FCC - AJ TRT7/TRT 7/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3678193","year":2024,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2819722","sourceQuestionId":"2819722","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, impenhorável","o":["o rendimento do bem inalienável em qualquer caso.","o seguro de vida.","o bem móvel que serve apenas para adornar escritório profissional.","o pertence de elevado valor de uso pessoal do executado.","a pequena propriedade rural, assim definida em lei, ainda que ociosa."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT12/TRT 12/Judiciária/\"Sem Especialidade\"/2023 • TEC 2819722","source":"FCC - AJ TRT12/TRT 12/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2819722","year":2023,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2820216","sourceQuestionId":"2820216","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, em caso de penhora de bens, o Oficial de Justiça realizará a avaliação quando","o":["houver bens que demandem conhecimentos especializados para avaliação, ainda que diante de execução que comporte a realização de avaliação específica por profissional indicado pelo juiz.","se tratar de títulos da dívida pública, de ações de sociedades e de títulos de crédito negociáveis em bolsa.","se tratar de títulos ou de mercadorias que tenham cotação em bolsa, ainda que haja comprovação por certidão ou publicação no órgão oficial.","se tratar de veículos automotores ou de outros bens cujo preço médio de mercado possa ser conhecido por meio de pesquisas realizadas por órgãos oficiais.","houver fundada dúvida do juiz quanto ao real valor do bem, no caso de uma das partes aceitar a estimativa feita pela outra."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT12/TRT 12/Judiciária/Oficial de Justiça Avaliador Federal/2023 • TEC 2820216","source":"FCC - AJ TRT12/TRT 12/Judiciária/Oficial de Justiça Avaliador Federal/2023","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2820216","year":2023,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2849464","sourceQuestionId":"2849464","t":"cpc-m17","moduleId":"cpc-m17","q":"De com as normas do Código de Processo Civil que disciplinam a execução por quantia certa, são formas de expropriação:","o":["a penhora e o arresto, apenas.","a adjudicação e a penhora, apenas.","a alienação, a adjudicação, o arresto, a penhora e a remição.","a alienação, a penhora e a remição, apenas.","a adjudicação, a alienação e a apropriação de frutos e rendimentos de empresa."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2023 • TEC 2849464","source":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2849464","year":2023,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2152379","sourceQuestionId":"2152379","t":"cpc-m17","moduleId":"cpc-m17","q":"Analise as proposições abaixo. I. Presume-se em fraude à execução a alienação ou a oneração de bens efetuada após a averbação de certidão da admissão da execução. II. Os bens inalienáveis são impenhoráveis, mas, à falta de outros bens, admite-se que se penhorem seus frutos e rendimentos. III. Os honorários advocatícios não serão devidos, na execução por quantia certa, se não houver oposição de embargos à execução. IV. A impenhorabilidade, quando decorrente da inalienabilidade, pode ser oposta à execução de dívida relativa ao próprio bem. Acerca da execução por quantia certa, está correto o que se afirma APENAS em","o":["I, III e IV.","II e III.","I e IV.","III e IV.","I e II."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022 • TEC 2152379","source":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2152379","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2154655","sourceQuestionId":"2154655","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, o oficial de justiça, no cumprimento de mandado de penhora,","o":["deverá se abster de penhorar bens do executado que estejam sob a posse, detenção ou guarda de terceiro, devendo, ao verificar tal circunstância, devolver o mandado sem cumprimento, descrevendo circunstanciadamente o ocorrido ao juiz.","tem autoridade, independentemente de prévia autorização do juiz, para realizar o arrombamento de portas e janelas, se o executado as fechar para obstar o cumprimento da ordem de penhora.","tem autoridade para autorizar o executado a alienar bens fungíveis sempre que houver risco de perecimento.","quando não encontrar bens penhoráveis, descreverá na certidão os bens que guarnecem a residência ou o estabelecimento do executado, quando este for pessoa jurídica, independentemente de determinação judicial expressa.","se não encontrar o executado, arrestar-lhe-á tantos bens quantos bastem para garantir a execução, desde que essa medida conste expressamente do mandado."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2154655","source":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2154655","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2154656","sourceQuestionId":"2154656","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, os bens móveis serão depositados","o":["excepcionalmente em poder do depositário judicial, somente nos casos em que houver risco de subtração ou perecimento dos bens caso sejam mantidos em poder de qualquer das partes.","obrigatoriamente em poder do depositário judicial, ou, na sua falta, em poder do executado, admitindo-se ainda o depósito em poder do exequente somente quando houver prévia autorização judicial nesse sentido.","preferencialmente em poder do depositário judicial, ou, na sua falta, em poder do executado, admitindo-se ainda o depósito em poder do exequente somente quando houver prévia autorização judicial nesse sentido.","preferencialmente em poder do executado, admitindo-se o depósito em poder do exequente quando anuir o executado; excepcionalmente, os bens poderão ser depositados em poder do depositário judicial quando nenhuma das partes aceitar o encargo.","preferencialmente em poder do depositário judicial, ou, na sua falta, em poder do exequente, admitindo-se ainda o depósito em poder do executado nos casos de difícil remoção ou quando anuir o exequente."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2154656","source":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2154656","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2154657","sourceQuestionId":"2154657","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, no caso de penhora de bem hipotecado, o executado poderá remi-lo","o":["até o prazo de 05 dias contado da juntada do auto penhora e avaliação aos autos, oferecendo preço igual ao da avaliação.","até a assinatura do auto de adjudicação, oferecendo preço igual ao da avaliação, se não tiver havido licitantes, ou ao do maior lance oferecido.","em qualquer momento anterior ao cumprimento do mandado de imissão na posse, oferecendo preço igual ao da avaliação, se não tiver havido licitantes, ou ao do lance vencedor.","até o prazo de 15 dias contado da juntada do auto penhora e avaliação aos autos, oferecendo preço igual ao da avaliação.","em qualquer momento anterior à expedição do mandado de imissão na posse, oferecendo preço igual ao da avaliação, ou ao do lance vencedor, se for maior."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2154657","source":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2154657","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2168607","sourceQuestionId":"2168607","t":"cpc-m17","moduleId":"cpc-m17","q":"No cumprimento de mandado de citação para a execução fundada em título extrajudicial, se não encontrar o executado, o oficial de justiça deverá","o":["penhorar tantos bens quantos bastem para garantir a execução, desde que exista suspeita de ocultação.","arrestar tantos bens quantos bastem para garantir a execução, independentemente de haver suspeita de ocultação.","arrestar tantos bens quantos bastem para garantir a execução, desde que exista suspeita de ocultação.","penhorar tantos bens quantos bastem para garantir a execução, independentemente de haver suspeita de ocultação.","penhorar tantos bens quantos bastem para garantir a execução e, se houver suspeita de ocultação, arrestá-los, entregando- os a depositário oficial."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2168607","source":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2168607","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2239324","sourceQuestionId":"2239324","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, em ação de execução por quantia certa, caberá ao oficial de justiça realizar o arresto dos bens do executado","o":["quando, no cumprimento do mandado de citação do devedor, deixar de encontrá-lo, caso em que a medida deverá atingir tantos bens quantos bastem para garantir a execução.","depois de penhorá-los, se suspeitar de tentativa do devedor de frustrar a execução mediante a ocultação desses bens, devendo a medida ser praticada independentemente de prévia autorização judicial.","quando, depois de avaliar os bens penhorados, verificar que eles são insuficientes para garantir a execução.","somente se os bens penhoráveis forem fungíveis.","depois de penhorá-los, se suspeitar de tentativa do devedor de frustrar a execução mediante a ocultação desses bens, devendo a medida ser precedida de prévia autorização judicial."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2239324","source":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2239324","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2272122","sourceQuestionId":"2272122","t":"cpc-m17","moduleId":"cpc-m17","q":"Em leilão judicial realizado em virtude de processo de execução por quantia certa, o Oficial de Justiça, de acordo com o Código de Processo Civil,","o":["não pode, em nenhuma hipótese, oferecer lance em relação aos bens e direitos objeto de alienação, mesmo que o processo tramite em localidade distinta daquela onde servir.","não pode oferecer lance em relação aos bens e direitos objeto de alienação na localidade onde servir, independentemente de ter ou não praticado ato no processo.","pode oferecer lance em relação aos bens e direitos objeto de alienação, inclusive na localidade onde servir, mesmo que já tenha praticado ato no processo.","pode oferecer lance em relação aos bens e direitos objeto de alienação, inclusive na localidade onde servir, salvo se já tiver praticado qualquer ato no processo.","pode oferecer lance em relação aos bens e direitos objeto de alienação, inclusive na localidade onde servir, salvo apenas se tiver avaliado esses bens ou direitos."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2272122","source":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2272122","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2272131","sourceQuestionId":"2272131","t":"cpc-m17","moduleId":"cpc-m17","q":"No cumprimento de mandado de penhora, se o executado fechar as portas da casa para impedir o acesso aos seus bens, caberá ao Oficial de Justiça","o":["proceder ao seu imediato arrombamento, independentemente de qualquer comunicação ao juiz ou de ordem judicial nesse sentido.","solicitar o concurso de outro oficial de justiça e, independentemente de ordem judicial específica neste sentido, proceder ao arrombamento.","comunicar o fato ao juiz, solicitando-lhe ordem de arrombamento, caso em que, deferido o pedido, o mandado será cumprido por dois oficiais de justiça.","solicitar o concurso policial, independentemente de autorização judicial, e, depois de arrombar a porta, prender o executado, apresentando-o imediatamente ao juiz.","comunicar o fato ao juiz, solicitando-lhe ordem de arrombamento, salvo se suspeitar que o executado está tentando destruir ou desviar seus bens, caso em que poderá realizar o arrombamento, independentemente de ordem judicial nesse sentido."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2272131","source":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2272131","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2296308","sourceQuestionId":"2296308","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o que estabelece o Código de Processo Civil acerca da penhora,","o":["é expressamente vedada a nomeação do executado ou seu representante legal como depositário provisório dos bens constantes da lista elaborada pelo oficial de justiça.","são igualmente impenhoráveis, mesmo que à falta de outros bens, os frutos e rendimentos dos bens inalienáveis.","para fins de substituição da penhora, equiparam-se a dinheiro a fiança bancária e o seguro garantia judicial, desde que em valor não inferior ao do débito constante da inicial, acrescido de dez por cento.","quando não encontrar bens penhoráveis, somente por expressa determinação judicial, é que o oficial de justiça descreverá na certidão os bens que guarnecem a residência ou o estabelecimento do executado, quando este for pessoa jurídica.","a penhora de dinheiro e as averbações de penhoras de bens imóveis e móveis podem ser realizadas por meio eletrônico, desde que obedecidas as normas de segurança instituídas sob critérios uniformes pelo Conselho Nacional de Justiça."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT5/TRT 5/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2296308","source":"FCC - AJ TRT5/TRT 5/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2296308","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1736847","sourceQuestionId":"1736847","t":"cpc-m17","moduleId":"cpc-m17","q":"A penhora","o":["não pode recair sobre os bens inalienáveis, seus frutos e rendimentos, mesmo que à falta de outros bens.","será comunicada ao executado, em regra, por meio de intimação a seu advogado ou à sociedade de advogados a que pertença.","que recaia sobre imóvel ou direito real sobre imóvel impõe a intimação do cônjuge do executado, qualquer que seja o regime de bens.","deve ser averbada no registro competente para que tenha efeito entre as partes do processo.","incidente sobre quotas autoriza que o exequente passe a integrar a sociedade empresária, na qualidade de sócio, salvo se os demais exercerem direito de preferência na aquisição."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736847","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736847","year":2021,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1752322","sourceQuestionId":"1752322","t":"cpc-m17","moduleId":"cpc-m17","q":"Paulo e Cláudia são casados em regime de comunhão parcial de bens. Paulo tem um filho de relacionamento anterior e estava em dívida com a sua obrigação alimentar há anos, situação desconhecida por Cláudia. O casal possui um único bem de família, adquirido na constância da união. Em cumprimento de sentença, foi penhorado o imóvel pertencente ao casal, intimando-se também Cláudia, por se tratar de coproprietária do bem. Diante da situação concreta,","o":["caso expropriado o imóvel, Cláudia terá direito a receber o valor correspondente à metade da avaliação do bem.","não há previsão legal de direito à preferência do cônjuge na arrematação do bem, ainda que em igualdade de condições com os demais interessados.","a fim de não prejudicar direito de terceiro alheio à execução, deve-se realizar a venda somente da cota-parte do devedor, formando-se, futuramente, um condomínio entre o arrematante e Cláudia.","tratando-se de bem indivisível, a única opção possível é a realização de leilão judicial, não podendo o exequente optar pela alienação particular do bem.","uma vez levado à hasta pública, a meeira terá direito à metade do produto da venda do bem, desde que não seja vendido por preço vil."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP GO/DPE GO/2021 • TEC 1752322","source":"FCC - DP GO/DPE GO/2021","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1752322","year":2021,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-609577","sourceQuestionId":"609577","t":"cpc-m17","moduleId":"cpc-m17","q":"No tocante à penhora,","o":["são impenhoráveis os vestuários, bem como os pertences de uso pessoal do devedor, ainda que de elevado valor.","a ordem de bens passíveis de penhora é taxativa e não admite flexibilização.","não é possível a penhora de percentual do faturamento de empresa devedora, por equivaler à penhora da própria empresa.","à falta de outros bens, podem ser penhorados os frutos e os rendimentos dos bens alienáveis.","quando não encontrar bens penhoráveis, e desde que haja determinação judicial expressa, o oficial de justiça certificará os bens que guarnecem a residência do devedor, para posterior penhora daqueles passíveis de gravame."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP (DPE AP)/DPE AP/2018 • TEC 609577","source":"FCC - DP (DPE AP)/DPE AP/2018","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/609577","year":2018,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-618098","sourceQuestionId":"618098","t":"cpc-m17","moduleId":"cpc-m17","q":"Na execução por quantia certa, em relação à penhora de bens:","o":["A penhora de crédito representado por letra de câmbio, nota promissória ou cheque far-se-á pela apreensão do documento, desde que este se encontre em poder do executado.","São impenhoráveis quaisquer móveis, pertences ou utilidades domésticas que guarnecem a residência do executado, bem como os pertences de seu uso pessoal.","O rol de bens a serem penhorados na execução segue ordem compulsória e é taxativo.","Não se procederá à segunda penhora, salvo, exclusivamente, se a primeira for anulada ou o produto da alienação dos bens for insuficiente.","Será admitida a redução ou a ampliação da penhora, bem como sua transferência para outros bens, se, no curso do processo, o valor de mercado dos bens penhorados sofrer alteração significativa."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador Federal/2018 • TEC 618098","source":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador Federal/2018","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/618098","year":2018,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-653963","sourceQuestionId":"653963","t":"cpc-m17","moduleId":"cpc-m17","q":"Na execução por quantia certa, nos termos preconizados pelo Código de Processo Civil, é correto afirmar:","o":["São impenhoráveis bens considerados inalienáveis, bem como os frutos e os rendimentos dos referidos bens, ainda que não existam outros bens passíveis de penhora.","Havendo pagamento integral da dívida pelo executado no prazo de até 5 dias após a regular citação, o valor dos honorários advocatícios será reduzido pela metade.","A penhora de bens do executado poderá ser levada a efeito ainda quando ficar evidente que o produto da execução dos bens encontrados será totalmente absorvido pelo pagamento das custas da execução.","Realizada a penhora on-line de dinheiro em depósito ou em aplicação financeira, consumada a indisponibilidade dos ativos financeiros, o executado será intimado na pessoa do seu advogado ou, não o tendo, pessoalmente, e terá o prazo de 5 dias para comprovar que as quantias tornadas indisponíveis são impenhoráveis.","Havendo requerimento de adjudicação de bem imóvel penhorado do executado em igualdade de ofertas, terá preferência o descendente, o cônjuge, o companheiro ou o ascendente, nessa ordem."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2018 • TEC 653963","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2018","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/653963","year":2018,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-664656","sourceQuestionId":"664656","t":"cpc-m17","moduleId":"cpc-m17","q":"Em relação à execução por quantia certa,","o":["o exequente poderá obter certidão de que a execução foi admitida pelo juiz, com identificação das partes e do valor da causa, para fins de averbação no registro de imóveis, de veículos ou de outros bens sujeitos a penhora, arresto ou indisponibilidade.","ao despachar a inicial, o juiz fixará, de plano, os honorários advocatícios de 15%, a serem pagos pelo executado, reduzindo-se esse valor a 5% em caso de pagamento integral no prazo de três dias.","o executado será intimado para pagar a dívida em três dias, ou nomear bens suficientes à satisfação do crédito.","se o oficial de justiça não encontrar o executado, devolverá o mandado em cartório, que intimará o exequente para indicar bens à penhora.","no prazo para oferecimento de embargos à execução, impreterivelmente, poderá o executado remir a execução pagando o débito com os encargos e acréscimos legais."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2018 • TEC 664656","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2018","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/664656","year":2018,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-476821","sourceQuestionId":"476821","t":"cpc-m17","moduleId":"cpc-m17","q":"José é credor de Joaquim da quantia de R$ 50.000,00 decorrente de contrato de empréstimo particular assinado pelas partes e por duas testemunhas. Vencido o prazo de um ano estabelecido para pagamento e inadimplida a obrigação José propõe ação de execução de quantia certa contra Joaquim com o escopo de receber o seu crédito, com juros e correção monetária. Ao despachar a inicial o juiz fixará, de plano, os honorários advocatícios de","o":["10%, a serem pagos pelo executado, que serão reduzidos pela metade no caso de integral pagamento da dívida no prazo de 5 dias.","10% a 20%, a serem pagos pelo executado, que serão reduzidos pela metade no caso de integral pagamento da dívida no prazo de 5 dias.","20%, a serem pagos pelo executado, que serão reduzidos pela metade no caso de integral pagamento no prazo de 5 dias.","20%, a serem pagos pelo executado, que serão reduzidos pela metade no caso de integral pagamento no prazo de 3 dias.","10%, a serem pagos pelo executado, que serão reduzidos pela metade no caso de integral pagamento da dívida no prazo de 3 dias."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT24/TRT 24/Judiciária/Oficial de Justiça Avaliador Federal/2017 • TEC 476821","source":"FCC - AJ TRT24/TRT 24/Judiciária/Oficial de Justiça Avaliador Federal/2017","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/476821","year":2017,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-537034","sourceQuestionId":"537034","t":"cpc-m17","moduleId":"cpc-m17","q":"Quanto à execução no Processo Civil, a legislação sobre a matéria estabelece:","o":["Não constitui violação dos deveres da parte a conduta do executado que, intimado, não indica ao juiz bens sujeitos à penhora.","Na execução por quantia certa, os honorários advocatícios de 10% serão fixados de plano pelo juiz ao despachar a petição inicial, cujo valor será reduzido pela metade se o executado pagar integralmente o valor, no prazo de três dias da citação ou poderá ser elevado a 20% quando rejeitados os embargos à execução ou, quando não opostos, levando-se em conta o trabalho realizado pelo advogado do exequente, conforme se constatar ao final do procedimento executivo.","Antes de adjudicados ou alienados os bens, o executado pode, a todo tempo, remir a execução, pagando ou consignando a importância atualizada da respectiva avaliação, acrescida das despesas decorrentes do leilão, inclusive honorários do leiloeiro.","São absolutamente impenhoráveis os vencimentos, subsídios, soldos, salários, remunerações, proventos de aposentadoria, pensões, pecúlios e montepios, bem como as quantias recebidas por liberalidade de terceiro e destinadas ao sustento do devedor e de sua família, os ganhos de trabalhador autônomo e os honorários de profissional liberal, exceto para pagamento de prestação alimentícia, independentemente de sua origem.","A penhora de crédito representado por letra de câmbio, nota promissória, duplicata, cheque ou outros títulos far-se-á exclusivamente pela apreensão do documento, podendo o juiz determinar, como medida preparatória do ato, a intimação do terceiro devedor para que não pague ao executado, seu credor e do executado, credor do terceiro, para que não pratique ato de disposição do crédito."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT (CSJT)/CSJT/2017 • TEC 537034","source":"FCC - JT (CSJT)/CSJT/2017","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/537034","year":2017,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-537084","sourceQuestionId":"537084","t":"cpc-m17","moduleId":"cpc-m17","q":"Sobre execução no Processo Civil, é correto afirmar:","o":["Ocorrendo penhora das quotas ou das ações de sócio em sociedade simples ou empresária, o juiz poderá determinar o leilão judicial quando não haja interesse dos demais sócios no exercício de direito de preferência, não ocorra a aquisição das quotas ou das ações pela própria sociedade e a liquidação seja excessivamente onerosa para a sociedade.","O executado poderá requerer a substituição do bem penhorado, devendo comprovar que a substituição lhe será menos onerosa, bem como indicar onde se encontram os bens sujeitos à execução, exibir a prova de sua propriedade e a certidão negativa ou positiva de ônus, bem como abster-se de qualquer atitude que dificulte ou embarace a realização da penhora, caso em que a substituição pode ser deferida ainda que haja prejuízo ao exequente.","Havendo penhora de pedras e metais preciosos, o juiz não poderá determinar a alienação antecipada dos bens, ainda que comprovada manifesta vantagem para a execução.","O juiz poderá ordenar a penhora de percentual de faturamento de empresa se o executado não tiver outros bens penhoráveis ou se, tendo-os, esses forem de difícil alienação ou insuficientes para saldar o crédito executado, caso em que fixará percentual que propicie a satisfação do crédito exequendo em tempo razoável, mas que não torne inviável o exercício da atividade empresarial, nunca inferior a dez ou superior a trinta por cento.","Caso a penhora recaia sobre estabelecimento comercial, o juiz nomeará administrador-depositário para dar continuidade ao negócio, podendo as partes ajustar a forma de administração, mas não a escolha do depositário."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT (CSJT)/CSJT/2017 • TEC 537084","source":"FCC - JT (CSJT)/CSJT/2017","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/537084","year":2017,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-396157","sourceQuestionId":"396157","t":"cpc-m17","moduleId":"cpc-m17","q":"Para possibilitar a penhora de dinheiro em depósito ou em aplicação financeira, o juiz,","o":["a requerimento do exequente, ouvindo previamente o executado, no prazo de três dias, determinará às instituições financeiras, por meio de sistema eletrônico gerido pela autoridade supervisora do sistema financeiro nacional, que torne indisponíveis ativos financeiros existentes em nome do executado.","de ofício, ouvindo previamente o executado, no prazo de três dias, determinará às instituições financeiras, por meio de sistema eletrônico gerido pela autoridade supervisora do sistema financeiro nacional, que torne indisponíveis ativos financeiros existentes em nome do executado.","a requerimento do exequente, sem dar ciência prévia do ato ao executado, determinará às instituições financeiras, por meio de sistema eletrônico gerido pela autoridade supervisora do sistema financeiro nacional, que torne indisponíveis ativos financeiros existentes em nome do executado.","a requerimento do exequente, ouvindo previamente o executado, no prazo de três dias, determinará, por meio de ofício dirigido à instituição financeira em que alocados os recursos, que esta torne indisponíveis ativos financeiros existentes em nome do executado.","de ofício, sem dar ciência prévia do ato ao executado, determinará, por meio de ofício dirigido à instituição financeira em que alocados os recursos, que esta torne indisponíveis ativos financeiros existentes em nome do executado."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2016 • TEC 396157","source":"FCC - DP BA/DPE BA/2016","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396157","year":2016,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-438251","sourceQuestionId":"438251","t":"cpc-m17","moduleId":"cpc-m17","q":"Na execução por quantia certa,","o":["a expropriação consistirá em adjudicação e alienação, bem como apropriação de frutos e rendimentos de empresa ou de estabelecimentos e de outros bens.","antes de adjudicados ou alienados os bens, o executado pode remir a execução, pagando ou consignando a importância histórica da dívida, sem acréscimo de juros ou honorários advocatícios.","o executado será citado para pagar a dívida no prazo de quinze dias, contado da citação ou da juntada do último mandado aos autos, em caso de mais de um executado, sob pena de multa de 10% sobre o valor da execução.","ao despachar a inicial, o juiz fixará, de plano, independentemente da oposição de embargos, honorários advocatícios de vinte por cento sobre o valor da causa, a serem pagos pelo executado, os quais são reduzidos à metade em caso de pagamento espontâneo da dívida.","se o oficial não encontrar o executado, arrestar-lhe-á tantos bens quantos bastem para garantir a execução, os quais serão convertidos em penhora, dispensando-se a citação do devedor."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2016 • TEC 438251","source":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2016","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/438251","year":2016,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-279612","sourceQuestionId":"279612","t":"cpc-m17","moduleId":"cpc-m17","q":"Falecendo o devedor, contra seu espólio foi movida execução por quantia certa, tendo como título executivo uma nota promissória por aquele emitida. Verificando o credor que o inventário era negativo, por não existirem bens, indicou à penhora seguro de vida de que era beneficiária a viúva, que fora casada sob o regime da comunhão universal de bens. Neste caso, o seguro","o":["poderá ser penhorado e o que sobejar da indenização será entregue à beneficiária.","não poderá ser penhorado e a execução deverá ser extinta.","não poderá ser penhorado e a execução deverá ser suspensa.","poderá ser penhorado, mas à viúva se permite opor ao credor apenas exceções que lhe sejam pessoais.","poderá ser penhorado, mas à viúva se permite opor ao credor somente as exceções pessoais que tinha o falecido."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Aud (TCE-CE)/TCE CE/2015 • TEC 279612","source":"FCC - Aud (TCE-CE)/TCE CE/2015","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/279612","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-279841","sourceQuestionId":"279841","t":"cpc-m17","moduleId":"cpc-m17","q":"E m relação à execução por quantia certa contra devedor solvente, considere: I. O seguro de vida é absolutamente impenhorável. II. O credor poderá, na inicial da execução, indicar bens do devedor a serem penhorados. III. Se o Oficial de Justiça não encontrar o devedor, arrestar-lhe-á tantos bens quantos bastem para garantir a execução. IV. Recaindo a penhora em dinheiro, em espécie ou em depósito ou em aplicação financeira, será intimado também o cônjuge do executado. V. Tratando-se de penhora em bem divisível, a meação do cônjuge alheio à execução recairá sobre o produto da alienação do bem. Está correto o que se afirma APENAS em","o":["I, II e III.","II, III, IV e V.","I, IV e V.","II, III e IV.","I e V."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Con (TCE-CE)/TCE CE/2015 • TEC 279841","source":"FCC - Proc Con (TCE-CE)/TCE CE/2015","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/279841","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-292734","sourceQuestionId":"292734","t":"cpc-m17","moduleId":"cpc-m17","q":"Nelson registrou a penhora de um caminhão em ação de execução de título extrajudicial ajuizada contra a empresa Dourado Entregas Ltda. Em momento posterior, Orlando registrou a penhora deste mesmo bem em execução de sentença trabalhista ajuizada contra a mesma empresa. No entanto, o produto obtido com o bem foi suficiente para pagar apenas um dos credores. O dinheiro será recebido por","o":["Orlando, porque registrou a penhora em momento posterior.","Nelson, porque registrou a penhora em primeiro lugar.","Nelson, porque não é possível haver duas penhoras sobre um mesmo bem.","Orlando e Nelson, em partes iguais, ante o princípio da isonomia entre os credores.","Orlando, porque possui título preferencial."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT3/TRT 3/Judiciária/Oficial de Justiça Avaliador Federal/2015 • TEC 292734","source":"FCC - AJ TRT3/TRT 3/Judiciária/Oficial de Justiça Avaliador Federal/2015","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/292734","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-292796","sourceQuestionId":"292796","t":"cpc-m17","moduleId":"cpc-m17","q":"Em execução por quantia certa contra devedor solvente, Juliano teve penhorado dinheiro, que alega ser provento de seu salário, o qual viria a ser utilizado, na integralidade, para a subsistência de sua família. Tal bem é","o":["impenhorável, cabendo ao executado comprovar tratar-se de bem de tal natureza.","penhorável, pois o processo executivo corre em benefício do credor.","impenhorável, cabendo ao exequente comprovar que o bem não se reveste de tal natureza.","impenhorável, salvo se tiver sido depositado em conta- poupança e tiver valor superior a 20 salários mínimos.","impenhorável, não necessitando de prova de que se reveste de tal natureza, por haver presunção absoluta nesse sentido."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT3/TRT 3/Judiciária/\"Sem Especialidade\"/2015 • TEC 292796","source":"FCC - AJ TRT3/TRT 3/Judiciária/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/292796","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-326489","sourceQuestionId":"326489","t":"cpc-m17","moduleId":"cpc-m17","q":"Doriva está executando Osório, que lhe deve R$ 100.000,00. Verificando o Oficial de Justiça que Osório só possui bens inalienáveis, não havendo outros passíveis de penhora,","o":["poderá penhorar esses bens inalienáveis, pela prevalência do direito de crédito em relação ao direito patrimonial do devedor.","devolverá o mandado ao juiz da causa, pela impossibilidade de penhora, determinando ao credor que indique bens do devedor disponíveis e passíveis de constrição.","deverá penhorar os frutos e rendimentos desses bens inalienáveis, sem exceção quanto à sua natureza e finalidade.","devolverá o mandado ao juiz da causa, pela impossibilidade de penhora, para que determine a expedição de mandado à Receita Federal, visando ao descobrimento de outros bens passíveis de constrição.","poderá penhorar os frutos e rendimentos desses bens inalienáveis, salvo se destinados à satisfação de prestação alimentícia."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2015 • TEC 326489","source":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2015","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326489","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-373379","sourceQuestionId":"373379","t":"cpc-m17","moduleId":"cpc-m17","q":"Na execução por quantia certa contra devedor solvente, não estão sujeitos à execução os bens que a lei considera impenhoráveis ou inalienáveis. Essa regra é","o":["verdadeira, tratando-se de regra absoluta tanto em relação aos bens em si como quanto a seus frutos e rendimentos, também não sujeitos a qualquer constrição judicial.","verdadeira, mas podem ser penhorados, à falta de outros bens, os frutos e rendimentos de quaisquer bens inalienáveis, sem restrições legais.","falsa, porque os bens inalienáveis podem, no entanto, ser livremente penhorados, tratando-se de situações jurídicas que não se confundem.","verdadeira, mas podem ser penhorados, à falta de outros bens, os frutos e rendimentos dos bens inalienáveis, salvo se destinados à satisfação de prestação alimentícia.","falsa, porque, em determinadas situações, expressamente previstas em lei, quaisquer bens podem ser penhorados ou alienados judicialmente para satisfação de créditos específicos."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373379","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373379","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-171803","sourceQuestionId":"171803","t":"cpc-m17","moduleId":"cpc-m17","q":"A respeito da execução em geral, considere: I. Podem ser penhoradas cotas sociais de sociedade limitada por dívida particular de sócio. II. Ficam sujeitos à execução os bens gravados com ônus real em fraude à execução. III. O fiador, quando executado, não poderá nomear à penhora bens livres e desembaraçados do devedor. Está correto o que consta APENAS em","o":["III.","I e III.","II e III.","II.","I e II."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2014 • TEC 171803","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2014","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/171803","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-173869","sourceQuestionId":"173869","t":"cpc-m17","moduleId":"cpc-m17","q":"Na posse de mandado de penhora, o oficial de justiça se dirige ao endereço residencial do devedor para a realização do ato. Chegando ao local, o devedor atende o oficial, mas não permite sua entrada, fechando as portas da casa, a fim de obstar a penhora dos bens. Neste caso, segundo o procedimento previsto pelo Código de Processo Civil, o oficial de justiça","o":["prosseguirá no cumprimento do mandado, arrombando portas, móveis e gavetas, onde presumir que se achem os bens, não sendo necessária ordem judicial expressa de arrombamento.","prosseguirá no cumprimento do mandado, requisitando auxílio de força policial para arrombar portas, móveis e gavetas, onde presumir que se achem os bens, não sendo necessária ordem judicial expressa de arrombamento.","comunicará o fato ao juiz, solicitando-lhe ordem de arrombamento, que deve ser expressa.","prosseguirá no cumprimento do mandado, arrestando tantos bens quantos bastem para garantir a execução, desde que possíveis de serem visualizados e identificados sem entrar na casa.","prosseguirá no cumprimento do mandado, arrombando portas, móveis e gavetas, onde presumir que se achem os bens, não sendo necessária ordem judicial expressa de arrombamento, e dará ordem de prisão ao devedor por resistir ao cumprimento da ordem judicial de penhora."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT19/TRT 19/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 173869","source":"FCC - AJ TRT19/TRT 19/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/173869","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-200970","sourceQuestionId":"200970","t":"cpc-m17","moduleId":"cpc-m17","q":"A respeito da execução por quantia certa contra devedor solvente, considere: I. O réu pode remir a execução, pagando ou consignando a importância atualizada da dívida, mais juros, custas e honorários advocatícios, até 30 dias após a penhora. II. Entre veículos de via terrestre e bens imóveis, a penhora recairá, preferencialmente, nos bens imóveis. III. Tratando-se de penhora de bem indivisível, a meação do cônjuge alheio à execução recairá sobre o produto da alienação do bem. Está correto o que se afirma APENAS em","o":["I e III.","I e II.","III.","II e III.","I."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT16/TRT 16/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 200970","source":"FCC - AJ TRT16/TRT 16/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/200970","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-212435","sourceQuestionId":"212435","t":"cpc-m17","moduleId":"cpc-m17","q":"Cícero é proprietário de uma lavanderia e está sendo executado por dívida bancária em execução por quantia certa contra devedor solvente. Dentre os bens que possui, o Oficial de Justiça encontrou máquinas instaladas na lavanderia; depósito em caderneta de poupança no valor de quarenta salários mínimos; seguro de vida; joias, como pertences de uso pessoal; livros, ferramentas e utensílios úteis ao exercício da atividade profissional. Nesse caso, o Oficial de Justiça, deverá","o":["penhorar as joias, apenas.","penhorar as joias e o depósito em caderneta de poupança, apenas.","penhorar as joias e as máquinas instaladas na lavanderia, apenas.","penhorar os livros e as ferramentas, apenas.","devolver o mandado, certificando não ter encontrado bens passíveis de penhora."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 212435","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/212435","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-254796","sourceQuestionId":"254796","t":"cpc-m17","moduleId":"cpc-m17","q":"José inadimpliu nota promissória. Em execução, o credor requereu a penhora de sua única geladeira, de máquina de serrar com a qual exerce a profissão de marceneiro e de quantia correspondente a sessenta salários mínimos depositada em caderneta de poupança. São penhoráveis","o":["todos os bens cuja penhora foi requerida pelo credor.","a máquina de serrar e quantia correspondente a vinte dos sessenta salários mínimos depositados em caderneta de poupança.","a máquina de serrar e quantia correspondente a sessenta salários mínimos depositados em caderneta de poupança.","apenas quantia correspondente a sessenta salários mínimos depositados em caderneta de poupança.","apenas quantia correspondente a vinte dos sessenta salários mínimos depositados em caderneta de poupança."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT1/TRT 1/2014 • TEC 254796","source":"FCC - JT TRT1/TRT 1/2014","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/254796","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-662314","sourceQuestionId":"662314","t":"cpc-m16","moduleId":"cpc-m16","q":"Nas demandas contra a Fazenda Pública, à luz das disposições do Código de Processo Civil,","o":["a execução de sentença condenatória deve ser feita em procedimento autônomo, citando a Fazenda para a oposição de embargos.","embora o trânsito em julgado não seja requisito legal para início do cumprimento de sentença, por força da Constituição antes dele não é possível expedir ordem de precatório ou requisição de pagamento de pequeno valor mesmo que se trate de verba de natureza alimentar.","caso a Fazenda seja intimada para pagar o débito, no prazo de quinze dias, e não realize pagamento voluntário no prazo, o débito será acrescido de multa de dez por cento e, também, de honorários de advogado de dez por cento.","não impugnada a execução ou rejeitadas as arguições da executada, o próprio juiz da causa expedirá precatório em favor do exequente.","no processo de conhecimento pelo procedimento comum, o prazo para resposta da Fazenda Pública deve ser contado em quádruplo, razão pela qual o prazo para contestação é de sessenta dias."],"a":1,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2018 • TEC 662314","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Processual Civil - Da Execução Contra a Fazenda Pública (art. 910)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/662314","year":2018,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-719796","sourceQuestionId":"719796","t":"cpc-m16","moduleId":"cpc-m16","q":"No tocante à execução contra a Fazenda Pública, é correto afirmar:","o":["A Fazenda Pública será intimada para opor embargos em trinta dias.","Não é cabível ação monitória contra a Fazenda Pública.","É cabível execução por título extrajudicial contra a Fazenda Pública.","Não opostos embargos, expedir-se-á precatório em favor do exequente, para pagamento imediato, qualquer que seja o valor exigido judicialmente por ele, haja vista o regime jurídico especial previsto em favor do ente fazendário.","Ao embargar, a Fazenda Pública só poderá alegar questões preliminares prejudiciais e, no mérito, pagamento ou compensação creditícia."],"a":2,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018 • TEC 719796","source":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018","subject":"Direito Processual Civil - Da Execução Contra a Fazenda Pública (art. 910)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/719796","year":2018,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883933","sourceQuestionId":"3883933","t":"cpc-m16","moduleId":"cpc-m16","q":"Em um cumprimento de sentença que determinou o pagamento de prestação alimentícia em que o(a) defensor(a) atua em favor do credor, após esgotadas as buscas típicas por bens nos sistemas informatizados disponíveis, o executado, que é empresário de sucesso mas não possui bens em nome próprio, continua inadimplente. A Defensoria requer a suspensão da CNH e do passaporte do devedor. De acordo com o Código de Processo Civil e a jurisprudência consolidada do STJ e STF, tais medidas atípicas","o":["devem ser aplicadas de forma automática sempre que houver o esgotamento das buscas de bens via sistemas conveniados ao Judiciário.","são vedadas em execuções de alimentos, pois a única medida coercitiva pessoal admitida pelo sistema é a prisão civil.","dependem de prévia alteração do título executivo judicial, sob pena de violação da coisa julgada.","são inconstitucionais por violarem o direito fundamental de ir e vir (liberdade de locomoção) do cidadão devedor.","podem ser deferidas em caráter subsidiário, desde que observados o contraditório e a proporcionalidade, e que haja indícios de que o devedor possui patrimônio oculto."],"a":4,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883933","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Da Execução de Alimentos (arts. 911 a 913)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883933","year":2026,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-1005260","sourceQuestionId":"1005260","t":"cpc-m16","moduleId":"cpc-m16","q":"Com respeito à execução da prestação alimentícia, considere: I. Na execução fundada em título executivo extrajudicial que contenha obrigação alimentar, o juiz mandará intimar o executado para, em 3 (três) dias, efetuar o pagamento das parcelas anteriores ao início da execução e das que se vencerem no seu curso, provar que o fez ou justificar a impossibilidade de fazê-lo. II. O débito alimentar que autoriza a prisão civil do alimentante é o que compreende as três prestações anteriores ao ajuizamento da execução e as que se vencerem no curso do processo. III. O cancelamento de pensão alimentícia de filho que atingiu a maioridade está sujeito à decisão judicial, mediante contraditório, ainda que nos próprios autos em que houver sido concedida. IV. Os efeitos da sentença que reduz, majora ou exonera o alimentante do pagamento retroagem à data do vencimento de cada parcela, defesas a repetibilidade e a compensação. Está correto o que se afirma APENAS em","o":["I e IV.","III e IV.","I, II e III.","II e III.","II, III e IV."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE MT)/MPE MT/2019 • TEC 1005260","source":"FCC - Prom Jus (MPE MT)/MPE MT/2019","subject":"Direito Processual Civil - Da Execução de Alimentos (arts. 911 a 913)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1005260","year":2019,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-893756","sourceQuestionId":"893756","t":"cpc-m16","moduleId":"cpc-m16","q":"João Roberto, que completou 18 anos no dia 1º de julho de 2015, comparece à Defensoria Pública na data de hoje, com uma sentença que condenou o seu pai a pagar alimentos no valor de um salário mínimo ao mês, desde a citação, ocorrida em 1º de julho de 1999. Os documentos apresentados pelo jovem revelam que o alimentante nunca pagou qualquer valor a título de alimentos, desde que foram fixados até a presente data, razão pela qual João Roberto deseja que seu pai pague todas as prestações, sob pena de prisão. João nunca foi emancipado e também não houve causa extintiva do poder familiar antes do atingimento da maioridade. Diante deste pedido do autor e considerando as informações constantes da narrativa acima, o defensor deverá:","o":["ajuizar uma ação de execução de alimentos cobrando os últimos dois últimos anos, únicas parcelas que não foram atingidas pela prescrição bienal, além de ajuizar ação revisional de alimentos, para comprovar que, apesar de atingida a maioridade, João ainda tem necessita dos alimentos.","informar João Roberto que não mais é possível a cobrança dos alimentos, uma vez que após atingida a maioridade, ocorre a exoneração do encargo alimentar e, além disso, embora o direito aos alimentos seja imprescritível, a cobrança das parcelas já prescreve no prazo de dois anos a partir do momento em que João Roberto atingiu os 16 anos e, portanto, passou a ser relativamente incapaz.","ajuizar duas ações de execução de alimentos: uma cobrando as três últimas parcelas vencidas e as que se vencerem no curso do processo, sob pena de prisão, e a outra cobrando as demais parcelas desde o mês de julho de 1999, requerendo que o alimentante faça o pagamento das parcelas vencidas, sob pena de penhora.","ajuizar uma única ação de execução de alimentos, pedindo que o alimentante pague todas as prestações desde o mês de julho de 1999, sob pena de prisão civil, diante do caráter da imprescritibilidade dos alimentos.","ajuizar duas ações de execução de alimentos, cobrando as três últimas parcelas vencidas e as que se vencerem no curso do processo, sob pena de prisão, e a outra cobrando as demais parcelas, mas somente as que não estejam prescritas, respeitado o prazo prescricional de 02 anos em relação às parcelas vencidas."],"a":2,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2015 • TEC 893756","source":"FCC - DP MA/DPE MA/2015","subject":"Direito Processual Civil - Da Execução de Alimentos (arts. 911 a 913)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/893756","year":2015,"caderno":5,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar. Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3679846","sourceQuestionId":"3679846","t":"cpc-m17","moduleId":"cpc-m17","q":"Sobre as defesas do executado é correto afirmar:","o":["Os embargos à execução serão oferecidos no prazo de 15 dias, que serão contados individualmente no caso de litisconsórcio passivo, a partir da juntada aos autos do respectivo comprovante de citação.","Não cabe a rejeição liminar dos embargos em razão de julgamento liminar de improcedência do pedido.","A possibilidade de impugnação não se aplica ao cumprimento provisório de sentença.","A impugnação ao cumprimento de sentença apresentada pela Fazenda Pública não exige a expressa indicação do valor, considerado o devido, porque é dispensada a apresentação de memória de cálculo demonstrativa do excesso alegado, por força do interesse público envolvido.","O prazo de 15 dias para apresentação de impugnação ao cumprimento de sentença conta-se da intimação do devedor para pagamento do débito, fluindo ambos os prazos simultaneamente."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2025 • TEC 3679846","source":"FCC - Proc (PGE TO)/PGE TO/2025","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3679846","year":2025,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3177393","sourceQuestionId":"3177393","t":"cpc-m17","moduleId":"cpc-m17","q":"Ulisses foi citado em ação de execução em razão do inadimplemento de divida constante de documento particular assinado pelo devedor e por duas testemunhas. Ulisses reconhece a divida, porém entende que o valor pleiteado estão superior ao devido no título. Nesse caso, Ulisses deverá opor embargos à execução","o":["mediante depósito prévio Integral do valor da causa indicado pelo exequente, sendo 30% no ato da petição Inicial e o restante com parcelamento em até 6 vezes.","mediante depósito prévio integral do valor da causa indicado pelo exequente.","independentemente de depósito prévio, porém devera declarar na petição inicial o valor que entende correto.","mediante depósito prévio de 30% do valor da causa indicado pelo exequente.","mediante depósito prévio do valor que entende correto."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT7/TRT 7/Judiciária/\"Sem Especialidade\"/2024 • TEC 3177393","source":"FCC - AJ TRT7/TRT 7/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3177393","year":2024,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3227499","sourceQuestionId":"3227499","t":"cpc-m17","moduleId":"cpc-m17","q":"Analise as proposições abaixo, acerca dos embargos à execução: I. Os embargos à execução possuem natureza de defesa & devem ser opostos nos próprios autos da execução. II. Os embargos à execução podem ser opostos independentemente do oferecimento de penhora, depósito ou caução. III. Quando há mais de um executado o prazo para embargar conta-se sempre da juntada aos autos do último comprovante de citação. IV. Nos embargos à execução, o executado poderá alegar qualquer matéria que lhe seria lícito alegar como defesa em processo de conhecimento. De acordo com o Código de Processo Civil, está coreto o que se afirma APENAS em","o":["I e II.","III e IV.","Il e IV.","I e III.","II e III"],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3227499","source":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3227499","year":2024,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1234850","sourceQuestionId":"1234850","t":"cpc-m17","moduleId":"cpc-m17","q":"No que se refere aos embargos à execução, a legislação vigente estabelece que:","o":["se a eles for concedido efeito suspensivo, isto não obstará a efetivação dos atos de substituição, de reforço ou de redução da penhora e de avaliação de bens.","se destinam a desconstituir a sentença que formou título para seu cumprimento.","dependem de garantia real ou fidejussória ao juízo para serem opostos.","permitem o parcelamento do débito, em até seis vezes, sem prejuízo da discussão sobre sua existência.","terão efeito suspensivo como regra geral, pela possibilidade de dano grave e irreparável futuro ao devedor."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Adv Leg (ALAP)/ALAP/Atividade de Serviços Jurídicos/Procurador/2020 • TEC 1234850","source":"FCC - Adv Leg (ALAP)/ALAP/Atividade de Serviços Jurídicos/Procurador/2020","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1234850","year":2020,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-739849","sourceQuestionId":"739849","t":"cpc-m17","moduleId":"cpc-m17","q":"Paulo e Roberto são demandados em uma ação de execução de título extrajudicial. Paulo, foi citado em 5 de novembro, e Roberto foi citado no dia 09 do mesmo mês. Paulo, sem que tenha assegurado o juízo, apresentou embargos à execução, alegando somente excesso de execução. Nesse caso, o início do prazo para os embargos é contado","o":["a partir da juntada do último comprovante de citação; os embargos de Paulo serão liminarmente rejeitados caso ele não tenha apresentado na petição o valor que entende correto e o demonstrativo discriminado e atualizado do seu cálculo.","separadamente para os executados, a partir da juntada do respectivo comprovante de citação; os embargos de Paulo serão liminarmente rejeitados em razão de não ter assegurado o juízo.","separadamente para os executados, a partir da juntada do respectivo comprovante de citação; os embargos de Paulo serão liminarmente rejeitados caso ele não tenha apresentado na petição o valor que entende correto e o demonstrativo discriminado e atualizadodo seu cálculo.","a partir da juntada do último comprovante de citação; os embargos de Paulo serão liminarmente rejeitados em razão de não ter assegurado o juízo.","a partir da juntada do último comprovante de citação; os embargos de Paulo devem ser conhecidos apesar de não ter assegurado o juízo ou apresentado na petição o valor que entende correto e o demonstrativo discriminado e atualizado do seu cálculo, pois tais requisitos não são exigidos por lei."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2018 • TEC 739849","source":"FCC - DP MA/DPE MA/2018","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/739849","year":2018,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-583664","sourceQuestionId":"583664","t":"cpc-m17","moduleId":"cpc-m17","q":"Anderson ajuizou ação de execução de título extrajudicial contra Paulo e seu irmão Renato, que foram regularmente citados pelo correio, sendo que o Aviso de Recebimento − A.R. da carta de citação entregue a Paulo foi juntado aos autos no dia 02/08/2017 e o A.R. da carta de citação entregue a Renato foi juntado aos autos em 08/08/2017. Nesse caso, considerando que os executados são representados por advogados distintos, o prazo para Paulo opor embargos à execução","o":["será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da sua própria carta de citação.","não será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da sua própria carta de citação.","será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da carta de citação de Renato.","não será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da carta de citação de Renato.","será contado em dobro, considerando-se dia do começo a data em que recebida a carta de citação, independentemente da data da juntada aos autos do respectivo aviso de recebimento."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2017 • TEC 583664","source":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/583664","year":2017,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337498","sourceQuestionId":"337498","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, os embargos do devedor serão","o":["recebidos, em regra, no efeito suspensivo, o qual poderá ser revogado a qualquer tempo, se o credor prestar caução idônea a compensar eventuais prejuízos que o devedor venha a sofrer com os atos expropriatórios.","oferecidos no prazo de 15 dias, contados da data em que o devedor receber o mandado de citação.","rejeitados liminarmente quando manifestamente protelatórios, dispensada, nesse caso, a prévia manifestação do exequente.","rejeitados liminarmente quando manifestamente protelatórios, caso em que o juiz imporá, em favor do Estado, multa em valor não superior a 10% do valor em execução.","recebidos, em regra, sem efeito suspensivo, o qual poderá ser concedido, independentemente de garantia da execução ou de outros requisitos, se relevantes os fundamentos dos embargos."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (São Luís)/Pref São Luís/2016 • TEC 337498","source":"FCC - Proc (São Luís)/Pref São Luís/2016","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337498","year":2016,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337643","sourceQuestionId":"337643","t":"cpc-m17","moduleId":"cpc-m17","q":"Os embargos do devedor serão opostos no prazo de","o":["dez dias, independentemente de penhora, depósito ou caução, não possuindo, em regra, efeito suspensivo, e devendo ser rejeitados, liminarmente, se o excesso de execução for seu único fundamento e o embargante não declarar, na petição inicial, o valor que entende correto, apresentando memória de cálculo.","quinze dias, independentemente de penhora, depósito ou caução, possuindo, em regra, efeito suspensivo, e devendo ser rejeitados, liminarmente, se o excesso de execução for seu único fundamento e o embargante não declarar, na petição inicial, o valor que entende correto, apresentando memória de cálculo, salvo se possível a emenda da inicial.","quinze dias, independentemente de penhora, depósito ou caução, não possuindo, em regra, efeito suspensivo, e devendo ser rejeitados, liminarmente, se o excesso de execução for seu único fundamento e o embargante não declarar, na petição inicial, o valor que entende correto, apresentando memória de cálculo.","dez dias, desde que tenha sido previamente garantido o juízo, possuindo, em regra, efeito suspensivo, e devendo ser rejeitados, liminarmente, se o excesso de execução for seu único fundamento e o embargante não declarar, na petição inicial, o valor que entende correto, apresentando memória de cálculo, salvo se possível a emenda da inicial.","quinze dias, desde que tenha sido previamente garantido o juízo, não possuindo, em regra, efeito suspensivo, e devendo ser rejeitados, liminarmente, se o excesso de execução for seu único fundamento e o embargante não declarar, na petição inicial, o valor que entende correto, apresentando memória de cálculo."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2016 • TEC 337643","source":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2016","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337643","year":2016,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337734","sourceQuestionId":"337734","t":"cpc-m17","moduleId":"cpc-m17","q":"Acerca dos embargos do devedor, considere: I. Caso haja litisconsórcio e os executados possuam procuradores diferentes, contar-se-á em dobro o prazo, de 15 dias, para oposição de embargos do devedor. II. Quando houver mais de um executado, salvo se forem cônjuges, o prazo para oposição de embargos do devedor será contado a partir da juntada do respectivo mandado citatório aos autos. III. Quando o excesso de execução for o fundamento único dos embargos, mas o embargante não indicar o valor que entende correto, nem juntar memória de cálculo, o Juiz deverá mandar emendar a petição inicial. IV. Nos embargos do devedor, admite-se apenas a produção de prova documental. Está correto o que consta APENAS em","o":["I e IV.","II e III.","I e III.","II.","I, III e IV."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2016 • TEC 337734","source":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2016","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337734","year":2016,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-410421","sourceQuestionId":"410421","t":"cpc-m17","moduleId":"cpc-m17","q":"Na execução de título extrajudicial, de acordo com o Código de Processo Civil, o executado poderá opor-se à execução por meio de embargos,","o":["desde que garantida por depósito.","desde que garantida por penhora.","independentemente da garantia do juízo.","desde que garantida por caução.","desde que garantida por fiança."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TNS (Pref Teresina)/Pref Teresina/Advogado/2016 • TEC 410421","source":"FCC - TNS (Pref Teresina)/Pref Teresina/Advogado/2016","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/410421","year":2016,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-259375","sourceQuestionId":"259375","t":"cpc-m17","moduleId":"cpc-m17","q":"Considere: I. O débito alimentar que autoriza a prisão civil do alimentante é o que compreende as três prestações anteriores ao ajuizamento da ação e as que se vencerem no curso do processo. II. A prisão civil do devedor de alimentos pode ser decretada, de ofício, pelo juiz. III. A concessão de efeito suspensivo aos embargos do executado impedirá a efetivação dos atos de penhora e de avaliação dos bens. IV. Nos embargos à execução contra a Fazenda Pública, considera-se inexigível o título judicial fundado em lei ou ato normativo declarado inconstitucional pelo Supremo Tribunal Federal. Está correto o que se afirma APENAS em","o":["I e IV.","II e III.","III e IV.","I e II.","I e III."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (CNMP)/CNMP/Apoio Jurídico/Direito/2015 • TEC 259375","source":"FCC - Ana (CNMP)/CNMP/Apoio Jurídico/Direito/2015","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/259375","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-279613","sourceQuestionId":"279613","t":"cpc-m17","moduleId":"cpc-m17","q":"A sentença que julga procedentes os embargos do devedor tem natureza","o":["constitutiva negativa.","condenatória.","meramente declaratória.","mandamental.","determinativa."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Aud (TCE-CE)/TCE CE/2015 • TEC 279613","source":"FCC - Aud (TCE-CE)/TCE CE/2015","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/279613","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-299133","sourceQuestionId":"299133","t":"cpc-m17","moduleId":"cpc-m17","q":"Em execução de título executivo extrajudicial, os embargos do devedor são oferecidos no prazo de 15 dias,","o":["não computável em dobro e contado da juntada aos autos do respectivo mandado de citação, e não do último, ainda que haja mais de um executado com procuradores diferentes, não tendo como requisito a prévia garantia do juízo.","computável em dobro e contado da juntada aos autos do último mandado de citação, se houver mais de um executado com procuradores diferentes, devendo ser precedido de garantia do juízo.","computável em dobro e contado da juntada aos autos do respectivo mandado de citação e não do último, se houver mais de um executado com procuradores diferentes, tendo como requisito a prévia garantia do juízo.","não computável em dobro, ainda que haja mais de um executado com procuradores diferentes, mas contado da juntada aos autos do último mandado de citação, não tendo como requisito a prévia garantia do juízo.","computável em dobro e contado da juntada aos autos do último mandado de citação, se houver mais de um executado com procuradores diferentes, não tendo como requisito a prévia garantia do juízo."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT4/TRT 4/Judiciária/\"Sem Especialidade\"/2015 • TEC 299133","source":"FCC - AJ TRT4/TRT 4/Judiciária/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/299133","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-299295","sourceQuestionId":"299295","t":"cpc-m17","moduleId":"cpc-m17","q":"O efeito suspensivo aos embargos do devedor","o":["aproveita aos demais executados que não hajam embargado a execução, mesmo que o respectivo fundamento diga respeito exclusivamente ao embargante.","perdura até julgamento definitivo dos embargos, não podendo ser revogado, ainda que cessadas as circunstâncias que motivaram o seu deferimento.","é medida excepcional, podendo ser concedido quando, a requerimento do embargante, houver relevância de seus fundamentos, perigo manifesto de dano de difícil ou incerta reparação e prévia garantia do juízo.","é a regra, devendo ser concedido de ofício, pelo juiz, quando houver relevância de seus fundamentos e periculum in mora.","é medida excepcional, podendo ser concedido de ofício quando houver relevância de seus fundamentos e perigo manifesto de dano de difícil ou incerta reparação, prescindindo-se de prévia garantia do juízo."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT4/TRT 4/Judiciária/Oficial de Justiça Avaliador Federal/2015 • TEC 299295","source":"FCC - AJ TRT4/TRT 4/Judiciária/Oficial de Justiça Avaliador Federal/2015","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/299295","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-300988","sourceQuestionId":"300988","t":"cpc-m17","moduleId":"cpc-m17","q":"Diante de uma execução de título executivo extrajudicial: I. os embargos do devedor têm natureza jurídica de ação, mas não suspendem a execução, uma vez que a lei condiciona o seu recebimento à existência de penhora. II. a objeção de pré-executividade tem caráter endoprocessual e pode ser apresentada mesmo após o prazo para os embargos, mas apresenta restrição no âmbito da cognição. III. a concessão de tutela antecipada em uma ação autônoma de impugnação pode suspender a ação executiva. IV. o devedor pode valer-se das defesas heterotópicas incidentalmente no processo executivo, independente de segurança do juízo. V. caso em embargos se alegue a inexistência do crédito e o excesso de execução, o embargante deve indicar a parcela incontroversa do débito em memorial de cálculo, sob pena de rejeição liminar dos em bargos. Está correto o que se afirma APENAS em","o":["I, III e IV.","I, II e III.","III, IV e V.","II, III, IV e V.","II, III e IV."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SP/DPE SP/2015 • TEC 300988","source":"FCC - DP SP/DPE SP/2015","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300988","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-326490","sourceQuestionId":"326490","t":"cpc-m17","moduleId":"cpc-m17","q":"Em relação aos embargos do devedor, é correto afirmar:","o":["Quando houver mais de um executado, o prazo para cada um deles embargar conta-se a partir da juntada do respectivo mandado citatório, mesmo que se tratem de cônjuges ou companheiros.","Para que os embargos sejam opostos, é pressuposto essencial que o Juízo se encontre garantido por meio de penhora, depósito ou caução.","Serão os embargos oferecidos no prazo de dez dias, contados da data da juntada aos autos do mandado de citação.","Serão os embargos do devedor rejeitados liminarmente quando intempestivos, quando inepta a petição de seu oferecimento ou quando manifestamente protelatórios.","Os embargos não terão nunca efeito suspensivo na instância de origem, devendo esse efeito ser obtido excepcionalmente, provados seus requisitos legais, por meio de agravo de instrumento na instância superior."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2015 • TEC 326490","source":"FCC - AJ TRT9/TRT 9/Judiciária/Oficial de Justiça Avaliador Federal/2015","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326490","year":2015,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-177947","sourceQuestionId":"177947","t":"cpc-m17","moduleId":"cpc-m17","q":"Considerando que Carlos e Daniel foram citados em execução de título executivo extrajudicial, analise as proposições abaixo. I. Se reconhecerem o crédito, Carlos e Daniel poderão, no prazo dos embargos, depositar 30% do valor da execução, incluindo custas e honorários, pagando o saldo remanescente em até 6 parcelas mensais, corrigidas monetariamente e acrescidas de juros de 1% ao mês. II. Caso tenham procuradores diferentes, Carlos e Daniel gozarão do prazo em dobro para apresentação de embargos. III. Carlos e Daniel poderão, uma vez garantido o juízo, apresentar embargos, no prazo de quinze dias, contado da data da juntada do último mandado aos autos. Está correto o que se afirma em","o":["I, II e III.","I, apenas.","II e III, apenas.","I e II, apenas.","I e III, apenas."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Jud (Pref Recife)/Pref Recife/2014 • TEC 177947","source":"FCC - Proc Jud (Pref Recife)/Pref Recife/2014","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/177947","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-200898","sourceQuestionId":"200898","t":"cpc-m17","moduleId":"cpc-m17","q":"Numa execução por quantia certa contra devedor solvente, os embargos do executado","o":["só poderão ser rejeitados liminarmente quando intempestivos.","só poderão ser opostos pelo executado se tiver ocorrido penhora, depósito ou caução.","deverão, em regra, ser processados com efeito suspensivo salvo entendimento judicial contrário, em decisão fundamentada.","serão oferecidos no prazo de 15 dias, contados da data da juntada aos autos do mandado de citação.","serão processados nos autos da execução, devendo o exequente ser ouvido no prazo de 10 dias."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT16/TRT 16/Judiciária/\"Sem Especialidade\"/2014 • TEC 200898","source":"FCC - AJ TRT16/TRT 16/Judiciária/\"Sem Especialidade\"/2014","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/200898","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-424253","sourceQuestionId":"424253","t":"cpc-m17","moduleId":"cpc-m17","q":"Em relação aos embargos do devedor, é correto afirmar:","o":["A decisão relativa aos efeitos dos embargos, se recebidos no duplo efeito ou somente no efeito devolutivo, é irrecorrível, por ausência de gravame.","Uma vez opostos, como regra conceder-se-á o efeito suspensivo da execução.","O Juiz os rejeitará liminarmente quando intempestivos, quando inepta a petição inicial, ou quando manifestamente procrastinatórios.","Serão oferecidos no prazo de 10 dias, contados da data da juntada aos autos do mandado de citação.","Quando houver mais de um executado, o prazo para embargar só se iniciará após a citação de todos os devedores."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJAP/TJ AP/2014 • TEC 424253","source":"FCC - JE TJAP/TJ AP/2014","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/424253","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2638100","sourceQuestionId":"2638100","t":"cpc-m17","moduleId":"cpc-m17","q":"No tocante aos embargos do devedor, é INCORRETO afirmar:","o":["Quando o efeito suspensivo atribuído aos embargos disser respeito apenas a parte do objeto da execução, esta prosseguirá quanto à parte restante.","A decisão relativa aos efeitos dos embargos poderá, a requerimento da parte, ser modificada ou revogada a qualquer tempo, em decisão fundamentada, cessando as circunstâncias que a motivaram.","Os embargos do devedor não terão efeito suspensivo, salvo apenas se disserem respeito a excesso de execução e estiverem garantidos por meio de caução idônea ou penhora suficiente.","A concessão de efeito suspensivo aos embargos oferecidos por um dos executados não suspenderá a execução contra os que não embargaram, quando o respectivo fundamento disser respeito exclusivamente ao embargante.","Quando o excesso de execução for fundamento dos embargos, o embargante deverá declarar na petição inicial o valor que entende correto, apresentando memória do cálculo, sob pena de rejeição liminar dos embargos ou de não conhecimento desse fundamento."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014 • TEC 2638100","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária e Administrativa/2014","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638100","year":2014,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2022859","sourceQuestionId":"2022859","t":"cpc-m17","moduleId":"cpc-m17","q":"A respeito da execução e temas correlatos,","o":["o termo inicial da prescrição no curso do processo será a ciência da primeira tentativa infrutífera de localização do devedor ou de bens penhoráveis, sendo ela passível de suspensão, por uma única vez, pelo prazo máximo de um ano.","a prescrição no curso do processo só poderá ser reconhecida se arguida pelo devedor ou terceiro interessado.","não serão praticados atos processuais de qualquer natureza, uma vez suspensa a execução.","se for conveniente às partes, o juiz declarará suspensa a execução durante o prazo máximo de 90 dias, a fim de que obtenham solução consensual para cumprimento da obrigação.","a execução suspensa em razão do oferecimento de embargos de devedor poderá prosseguir, inclusive com a prática de atos de expropriação, se oferecida caução pelo credor."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AM)/PGE AM/2022 • TEC 2022859","source":"FCC - Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Suspensão e da Extinção do Processo de Execução (arts. 921 a 925)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2022859","year":2022,"caderno":5,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937742","sourceQuestionId":"3937742","t":"cpc-m20","moduleId":"cpc-m20","q":"Caíque compareceu à Defensoria Pública do Maranhão com dúvidas sobre o cabimento de ação rescisória para um processo em que foi parte. Sobre o assunto, ele deverá ser corretamente orientado que","o":["o Ministério Público tem legitimidade para propor a ação rescisória apenas nos casos em que a decisão rescindenda for o efeito de colusão das partes, a fim de fraudar a lei.","é rescindível a decisão transitada em julgado que, embora não seja de mérito, impeça nova propositura da demanda.","em regra, a mera propositura da ação rescisória impede o cumprimento da decisão rescindenda.","o direito à rescisão se extingue em 5 anos contados do trânsito em julgado da última decisão proferida no processo.","a ação rescisória deve atacar todos os capítulos da decisão rescindenda, sendo vedado ter por objeto apenas parte dos capítulos."],"a":1,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937742","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937742","year":2026,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3472593","sourceQuestionId":"3472593","t":"cpc-m20","moduleId":"cpc-m20","q":"Clara ajuizou ação de divórcio cumulada com pedido de guarda e alimentos perante a 2ª Vara de Família e das Sucessões da Comarca de Manaus-AM, por intermédio da Defensoria Pública local. O Juiz, ao receber a inicial, determinou o encaminhamento dos autos ao CEJUSC para a tentativa de acordo entre as partes. No CEJUSC, as partes compareceram sem a presença de suas defesas técnicas e formularam acordo. O acordo foi homologado judicialmente, com trânsito em julgado. Dias depois, Clara compareceu novamente em atendimento na Defensoria Pública e informou que havia sido vítima de violência doméstica e se sentiu coagida a aceitar o acordo. Nesse caso, a Defensoria Pública deverá","o":["peticionar pedido de reconsideração, nos próprios autos, direcionado ao Juízo da 2ª Vara de Família e das Sucessões da Comarca de Manaus.","opor embargos de declaração, direcionados ao Juízo da 2ª Vara de Família e das Sucessões da Comarca de Manaus.","ajuizar ação rescisória direcionada ao Tribunal de Justiça do Estado do Amazonas.","ajuizar ação revisional direcionada ao Juízo da 2ª Vara de Família e das Sucessões da Comarca de Manaus.","ajuizar ação anulatória direcionada ao Juízo da 2ª Vara de Família e das Sucessões da Comarca de Manaus."],"a":4,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2025 • TEC 3472593","source":"FCC - DP AM/DPE AM/2025","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3472593","year":2025,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3690936","sourceQuestionId":"3690936","t":"cpc-m20","moduleId":"cpc-m20","q":"Acerca da ação rescisória, considere: I. Pode ter por objeto apenas um capítulo da decisão. II. Poderá ser ajuizada por terceiro juridicamente interessado. III. O ajuizamento da ação rescisória, desde logo, impede o cumprimento da decisão rescindenda, ressalvada a concessão de tutela provisória. IV. Pode ter por objeto atos de disposição de direitos, praticados pelas partes ou por outros participantes do processo e homologados pelo juízo. V. Poderá ser ajuizada contra decisão de mérito, transitada em julgado, proferida por juízo relativamente incompetente. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS em","o":["IV e V.","I e II.","I e V.","II e III.","III e IV."],"a":1,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2025 • TEC 3690936","source":"FCC - Proc (UNICAMP)/UNICAMP/2025","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3690936","year":2025,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2340152","sourceQuestionId":"2340152","t":"cpc-m20","moduleId":"cpc-m20","q":"Em ação de cobrança movida por Luiza contra Janaína, o pedido foi julgado parcialmente procedente por sentença transitada em julgado, que condenou Janaína ao pagamento de metade do montante pleiteado por Luiza. Considerando que, em face da condenação sofrida, Janaína tem direito de regresso contra Rodrigo, o Código de Processo Civil confere legitimidade para propor ação rescisória dessa sentença à","o":["Luiza, somente.","Janaína, somente.","Luiza e à Janaína, somente.","Janaína e ao Rodrigo, somente.","Luiza, à Janaína e ao Rodrigo."],"a":4,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT18/TRT 18/Judiciária/Oficial de Justiça Avaliador Federal/2023 • TEC 2340152","source":"FCC - AJ TRT18/TRT 18/Judiciária/Oficial de Justiça Avaliador Federal/2023","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2340152","year":2023,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2038250","sourceQuestionId":"2038250","t":"cpc-m20","moduleId":"cpc-m20","q":"A ação rescisória é cabível em face de decisão transitada em julgado","o":["de mérito, que violar manifestamente norma jurídica de direto material, não sendo permitido o seu ajuizamento em caso de suposta violação de norma jurídica de direito processual.","que, embora não seja de mérito, impeça o ajuizamento de nova demanda.","de mérito, proferida por juiz suspeito.","de mérito, abrangendo todos os capítulos decisórios, pois não é possível impugnar somente um dos capítulos.","de atos homologatórios praticados no curso da execução."],"a":1,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP CE/DPE CE/2022 • TEC 2038250","source":"FCC - DP CE/DPE CE/2022","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2038250","year":2022,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2073357","sourceQuestionId":"2073357","t":"cpc-m20","moduleId":"cpc-m20","q":"Em relação à ação rescisória, considere: I. A decisão de mérito, transitada em julgado, entre outras hipóteses pode ser rescindida quando for proferida por juiz impedido ou por juízo relativa ou absolutamente incompetente. II. A propositura da ação rescisória não impede o cumprimento da decisão rescindenda, ressalvada a concessão de tutela provisória. III. Cabe ação rescisória, com fundamento na violação manifesta da norma jurídica, contra decisão baseada em enunciado de súmula ou acórdão proferido em julgamento de casos repetitivos que tenha considerado a existência de distinção entre a questão discutida no processo e o padrão decisório que lhe deu fundamento. IV. O direito à rescisão se extingue em 2 anos contados do trânsito em julgado da última decisão proferida no processo. Está correto o que se afirma APENAS em","o":["II, III e IV.","I e III.","II e IV.","I, III e IV.","I e II."],"a":2,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Teresina)/Pref Teresina/2022 • TEC 2073357","source":"FCC - Proc (Teresina)/Pref Teresina/2022","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2073357","year":2022,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2168707","sourceQuestionId":"2168707","t":"cpc-m20","moduleId":"cpc-m20","q":"De acordo com o Código de Processo Civil, a decisão de mérito transitada em julgado que ofender a coisa julgada","o":["não pode ser impugnada por ação rescisória ou anulatória, mas sua ineficácia pode ser incidentalmente declarada em qualquer processo.","não pode ser impugnada por ação rescisória, mas apenas por ação anulatória, que só pode ser proposta por quem foi parte na ação em que tal decisão foi proferida.","não pode ser impugnada por ação rescisória, mas apenas por ação anulatória, que pode ser proposta pelo terceiro juridicamente interessado.","pode ser impugnada por ação rescisória, que só pode ser proposta por quem foi parte na ação em que tal decisão foi proferida.","pode ser impugnada por ação rescisória, que pode ser proposta até mesmo pelo terceiro juridicamente interessado."],"a":4,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2022 • TEC 2168707","source":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2168707","year":2022,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2212012","sourceQuestionId":"2212012","t":"cpc-m20","moduleId":"cpc-m20","q":"Cláudia compareceu ao Núcleo Regional da Defensoria Pública em Laranjal do Jari, afirmando que tomou conhecimento de que seu ex-companheiro ajuizou ação de reconhecimento e dissolução de união estável contra ela e que gostaria de apresentar defesa. Ao consultar a íntegra do processo, a defensora pública verificou que a ação havia se encerrado com trânsito em julgado há três anos. A ação contava citação por carta com aviso de recebimento mediante assinatura falsa de Cláudia. Diante disso, foi decretada a sua revelia, pois Cláudia teria recebido a carta de citação e não teria apresentado defesa nos autos. Neste caso, a defensora pública poderá propor","o":["querela nullitatis, que está sujeita a prazo prescricional de quatro anos, ao juízo ad quem, necessariamente superior ao juízo que proferiu a decisão.","querela nullitatis, que não está sujeita a prazo decadencial, ao juízo ad quem, necessariamente superior ao juízo que proferiu a decisão.","ação rescisória, que está sujeita a prazo prescricional de quatro anos, ao juízo que proferiu a decisão nula.","ação rescisória, que não está sujeita a prazo decadencial, ao juízo ad quem, necessariamente superior ao juízo que proferiu a decisão.","querela nullitatis, que não está sujeita a prazo decadencial, ao juízo que proferiu a decisão nula."],"a":4,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP (DPE AP)/DPE AP/2022 • TEC 2212012","source":"FCC - DP (DPE AP)/DPE AP/2022","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2212012","year":2022,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2212015","sourceQuestionId":"2212015","t":"cpc-m20","moduleId":"cpc-m20","q":"Considere as assertivas abaixo a respeito do prazo para a ação rescisória. I. Tem natureza jurídica de prazo decadencial. II. Conta-se a partir do trânsito em julgado da decisão rescindenda na hipótese de decisão interlocutória parcial de mérito. III. Conta-se em dobro o prazo para a Defensoria Pública. IV. Quando o prazo se expirar em dia que não houver expediente forense, será prorrogado até o primeiro dia útil imediatamente subsequente. V. Caso a ação rescisória tenha por fundamento prova nova, o prazo para a propositura da ação será de cinco anos após o trânsito em julgado da última decisão proferida no processo. Está correto o que se afirma APENAS em","o":["I, II, IV e V.","I, II e III.","II, III e V.","IV e V.","I e IV."],"a":4,"e":"Tema classificado no Módulo 20: Processos nos tribunais, rescisória, IAC, IRDR e reclamação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP (DPE AP)/DPE AP/2022 • TEC 2212015","source":"FCC - DP (DPE AP)/DPE AP/2022","subject":"Direito Processual Civil - Da Ação Rescisória (arts. 966 a 975)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2212015","year":2022,"caderno":5,"classificationReason":"Processo ou incidente de tribunal expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
